{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Naltrexone, the closest analogue (Morgan 0.7119) sharing the 3-hydroxy-6-keto-14-hydroxy morphinan scaffold, has an oral bioavailability of ~5% in healthy volunteers due to extensive first-pass hepatic metabolism, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "M6G, another 3-phenolic morphinan, has poor oral bioavailability and is therefore given intravenously, reinforcing the first-pass liability of free 3-phenolic morphinans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Nalmefene, a 6-methylene analogue of naltrexone, reaches ~53% absolute oral bioavailability with food, showing that C6 modification can raise F, but the query retains the 6-keto group closer to low-F naltrexone.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "Morphine, an N-methyl 3-phenolic morphinan, has mean absolute oral bioavailability of 29.2%, above the threshold; however, the query's 6-keto/14-hydroxy substitution differs and is associated with more extensive first-pass metabolism.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C28"],
      "claim": "Samidorphan has 69% absolute oral bioavailability, but its low similarity and additional structural modifications limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is oxymorphone, a 3-phenolic N-methyl morphinan with 6-keto and 14-hydroxy groups. The closest analogue naltrexone (0.7119) is repeatedly reported with poor/low oral bioavailability (~5-20%), and the shared free 3-phenolic group is a known first-pass liability. Higher-F analogues either lack the 6-keto/14-OH combination (morphine), carry a 6-methylene modification (nalmefene), or have substantial structural changes (samidorphan, naloxegol), reducing their transferability. Weighing the direct scaffold match and first-pass metabolism pattern, F < 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability record for oxymorphone (the query) is present in the evidence set.",
    "Naltrexone, the closest analogue, has widely variable reported F values (5-60%), creating threshold uncertainty.",
    "No head-to-head comparison of oxymorphone with naltrexone or morphine under identical conditions is available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

